<script>  import { getStrings } from '../strings.svelte.js';  import { navStore } from '../stores/navigation.svelte.js';  const strings = $derived(getStrings());</script><nav class="tabs no-select" role="tablist">  {#each navStore.sections as section (section.id)}    {@const Icon = section.icon}    <button      type="button"      class="tabs__item"      class:active={navStore.current === section.id}      role="tab"      aria-selected={navStore.current === section.id}      onclick={() => navStore.current = section.id}    >      <Icon size={18} strokeWidth={2} />      <span>{strings.sections[section.id]}</span>    </button>  {/each}</nav><style>  .tabs {    display: flex;    flex-direction: column;    gap: 2px;    margin-bottom: var(--space-3);  }  .tabs__item {    display: flex;    align-items: center;    gap: var(--space-2);    width: 100%;    min-height: var(--touch-target);    padding: var(--space-2) var(--space-3);    border-radius: var(--radius-md);    color: var(--text-secondary);    font-size: var(--font-size-base);    text-align: left;    transition: background var(--transition-fast), color var(--transition-fast);  }  .tabs__item:hover {    background: var(--bg-elevated-2);    color: var(--text-primary);  }  .tabs__item.active {    background: var(--accent-dim);    color: var(--accent);    font-weight: 600;  }</style>